package udea.integrador.ingenote.application.service;
import udea.integrador.ingenote.application.exception.*; import udea.integrador.ingenote.application.port.in.ForoUseCase; import udea.integrador.ingenote.domain.model.*; import udea.integrador.ingenote.domain.port.out.*; import java.time.LocalDateTime; import java.util.*;
public class ForoService implements ForoUseCase {
 private final ForoPersistencePort foros; private final RecursoPersistencePort recursos; private final UsuarioPersistencePort usuarios; public ForoService(ForoPersistencePort f,RecursoPersistencePort r,UsuarioPersistencePort u){foros=f;recursos=r;usuarios=u;}
 private Usuario usuario(String c){return usuarios.buscarPorCorreo(c).orElseThrow(()->new AccesoDenegadoException("Usuario autenticado no encontrado"));} private boolean admin(Usuario u){return "ADMINISTRADOR".equalsIgnoreCase(u.rol().nombre());} private void autor(Usuario u,Usuario owner){if(!admin(u)&&!u.id().equals(owner.id()))throw new AccesoDenegadoException("No tiene permiso sobre este contenido");} private String texto(String x,String campo){if(x==null||x.isBlank())throw new ReglaDeNegocioException(campo+" es obligatorio");return x.trim();}
 public ForoHilo crearHilo(String c,UUID a,String t,String x){Usuario u=usuario(c);Asignatura as=recursos.buscarAsignaturaPorId(a).orElseThrow(()->new ReglaDeNegocioException("No existe la asignatura"));return foros.guardarHilo(new ForoHilo(null,as,u,texto(t,"El título"),texto(x,"El contenido"),LocalDateTime.now()));}
 public ForoHilo editarHilo(String c,UUID id,String t,String x){Usuario u=usuario(c);ForoHilo h=detalle(id);autor(u,h.autor());return foros.guardarHilo(new ForoHilo(h.id(),h.asignatura(),h.autor(),texto(t,"El título"),texto(x,"El contenido"),h.fechaCreacion()));} public void eliminarHilo(String c,UUID id){Usuario u=usuario(c);autor(u,detalle(id).autor());foros.eliminarHilo(id);} public List<ForoHilo> listar(UUID a,int p,int s){return foros.listarHilos(a,p,s);} public long contarHilos(UUID a){return foros.contarHilos(a);} public long contarRespuestas(UUID id){return foros.contarRespuestas(id);} public ForoHilo detalle(UUID id){return foros.buscarHilo(id).orElseThrow(()->new ReglaDeNegocioException("No existe el hilo"));}
 public ForoRespuesta responder(String c,UUID id,String x){return foros.guardarRespuesta(new ForoRespuesta(null,detalle(id).id(),usuario(c),texto(x,"El contenido"),LocalDateTime.now()));} public ForoRespuesta editarRespuesta(String c,UUID id,String x){Usuario u=usuario(c);ForoRespuesta r=foros.buscarRespuesta(id).orElseThrow(()->new ReglaDeNegocioException("No existe la respuesta"));autor(u,r.autor());return foros.guardarRespuesta(new ForoRespuesta(r.id(),r.hiloId(),r.autor(),texto(x,"El contenido"),r.fechaCreacion()));} public void eliminarRespuesta(String c,UUID id){Usuario u=usuario(c);ForoRespuesta r=foros.buscarRespuesta(id).orElseThrow(()->new ReglaDeNegocioException("No existe la respuesta"));autor(u,r.autor());foros.eliminarRespuesta(id);} public List<ForoRespuesta> respuestas(UUID h){detalle(h);return foros.listarRespuestas(h);}
 public void marcarSolucion(String c,UUID h,UUID r){Usuario u=usuario(c);autor(u,detalle(h).autor());ForoRespuesta x=foros.buscarRespuesta(r).orElseThrow(()->new ReglaDeNegocioException("No existe la respuesta"));if(!h.equals(x.hiloId()))throw new ReglaDeNegocioException("La respuesta no pertenece al hilo");throw new ReglaDeNegocioException("El esquema actual no puede persistir la solución. Agregue id_respuesta_solucion a tbl_foro_hilo o una tabla de relación mediante migración.");}
}
